-- ----------------------------------------------------------------------------
-- vw_owners: Entities (organizations or individuals) that own Types, Enums, and Formats. Sourced from definitions/owners.yaml.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW vw_owners WITH (security_invoker = ON) AS
SELECT
  t.owners_id,                                                                  -- Primary key (auto-synthesized: Owners had no field named 'Id' or ending in 'Id').
  t.name,                                                                       -- Owner identifier slug. Example: 'gridworks-energy'. Acts as the primary key.
  t.owner_type,                                                                 -- Either 'organization' or 'individual'.
  t.contact,                                                                    -- Primary contact email.
  t.website,                                                                    -- Owner's website URL.
  t.github,                                                                     -- Owner's GitHub URL (optional).
  t.organization,                                                               -- Full legal/organization name.
  t.description,                                                                -- Free-text description of the owner's domain or focus.
  t.support_policy,                                                             -- How users get support from this owner.
  t.license,                                                                    -- License under which the owner's contributions are published (e.g. 'MIT').
  calc_owners_is_organization(t.owners_id) AS is_organization,                  -- True when OwnerType is 'organization' (vs 'individual'). Cheap classifier for grouping owners.
  calc_owners_has_github(t.owners_id) AS has_github,                            -- True when this owner has a Github URL on file.
  calc_owners_format_count(t.owners_id) AS format_count,                        -- Number of Formats owned by this owner.
  calc_owners_enum_count(t.owners_id) AS enum_count,                            -- Number of Enums owned by this owner.
  calc_owners_type_count(t.owners_id) AS type_count,                            -- Number of Types owned by this owner.
  calc_owners_draft_type_version_count(t.owners_id) AS draft_type_version_count,-- Number of draft TypeVersions across all this owner's Words. Drives §7 'drafts open: N' badge on the Vocabularies grid.
  calc_owners_published_type_version_count(t.owners_id) AS published_type_version_count,-- Number of published TypeVersions.
  calc_owners_draft_enum_version_count(t.owners_id) AS draft_enum_version_count,-- Number of draft EnumVersions across this owner's Enums.
  calc_owners_published_enum_version_count(t.owners_id) AS published_enum_version_count,-- Number of published EnumVersions.
  calc_owners_has_open_drafts(t.owners_id) AS has_open_drafts,                  -- True iff this owner has any draft Type or Enum versions. Drives the amber dot on the Vocabularies card.
  calc_owners_has_published_artifacts(t.owners_id) AS has_published_artifacts,  -- True iff this owner has any artifacts at all (Types, Enums, or Formats). Drives empty-state vs populated rendering.
  calc_owners_latest_type_version_at(t.owners_id) AS latest_type_version_at,    -- Most recent TypeVersions.Created among this owner's Words.
  calc_owners_latest_enum_version_at(t.owners_id) AS latest_enum_version_at,    -- Most recent EnumVersions.Created among this owner's Enums.
  calc_owners_latest_format_at(t.owners_id) AS latest_format_at                 -- Most recent Formats.Created among this owner's Formats.
FROM owners t;

-- ----------------------------------------------------------------------------
-- vw_formats: JSON-Schema string formats with regex patterns and length bounds. Sourced from definitions/formats/*.yaml. Formats are not versioned.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW vw_formats WITH (security_invoker = ON) AS
SELECT
  t.formats_id,                                                                 -- Primary key (auto-synthesized: Formats had no field named 'Id' or ending in 'Id').
  t.name,                                                                       -- Format identifier slug. Example: 'uuid4.str'. Acts as the primary key.
  t.owner,                                                                      -- Owner of this format.
  t.schema_url,                                                                 -- Schema URL from JSON-Schema $id.
  t.title,                                                                      -- Human-readable title.
  t.description,                                                                -- Free-text description of the format.
  t.replaced_by,                                                                -- Advisory pointer to another Format that supersedes this one. The original Format remains valid and queryable — ReplacedBy is just a hint to consumers about a preferred successor. NOT a state change; published versions are immutable.
  t.pattern,                                                                    -- Regex pattern that valid values must match.
  t.min_length,                                                                 -- Minimum string length, if constrained.
  t.max_length,                                                                 -- Maximum string length, if constrained.
  t.json_schema_format,                                                         -- JSON-Schema 'format' keyword if present (e.g. 'date-time', 'email').
  t.created,                                                                    -- Created timestamp from registry.yaml.
  t.raw_json,                                                                   -- Escape hatch: any unmodeled JSON-Schema fields, serialized as JSON string.
  calc_formats_has_pattern(t.formats_id) AS has_pattern,                        -- True when a regex Pattern constraint is defined.
  calc_formats_has_length_bounds(t.formats_id) AS has_length_bounds,            -- True when at least one of MinLength / MaxLength is defined.
  calc_formats_example_count(t.formats_id) AS example_count,                    -- Number of positive examples on this format (FormatExamples where IsCounter=false).
  calc_formats_counter_example_count(t.formats_id) AS counter_example_count,    -- Number of counterexamples on this format (FormatExamples where IsCounter=true).
  calc_formats_type_attribute_usage_count(t.formats_id) AS type_attribute_usage_count,-- Number of TypeAttributes that point at this Format via FormatRef.
  calc_formats_type_helper_attribute_usage_count(t.formats_id) AS type_helper_attribute_usage_count,-- Number of TypeHelperAttributes that point at this Format via FormatRef.
  calc_formats_total_usage_count(t.formats_id) AS total_usage_count,            -- Total references across TypeAttributes + TypeHelperAttributes (sum of the two usage counts).
  calc_formats_is_used(t.formats_id) AS is_used,                                -- True when at least one TypeAttribute or TypeHelperAttribute references this format.
  calc_formats_is_unused(t.formats_id) AS is_unused,                            -- True when no attribute references this format — candidate for removal.
  calc_formats_owner_name(t.formats_id) AS owner_name                           -- Owner of this Format, passed through from Formats.Owner. Symmetry with TypeVersions.OwnerName / EnumVersions.OwnerName so list views render owner uniformly.
FROM formats t;

-- ----------------------------------------------------------------------------
-- vw_format_examples: Per-format examples and counterexamples (with order preserved). Sourced from format YAML 'examples' and 'counterexamples' arrays.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW vw_format_examples WITH (security_invoker = ON) AS
SELECT
  t.format_examples_id,                                                         -- Primary key (auto-synthesized: FormatExamples had no field named 'Id' or ending in 'Id').
  calc_format_examples_name(t.format_examples_id) AS name,                      -- Compound key combining the parent format, ordering index, and counterexample flag.
  t.format,                                                                     -- Foreign key to the parent Format.
  t.idx,                                                                        -- Preserves YAML ordering (0-indexed within examples or counterexamples).
  t.is_counter,                                                                 -- True if this is a counterexample (must NOT match), false if a positive example.
  t.value,                                                                      -- The example string itself.
  t.description,                                                                -- Optional description (e.g. YAML inline comment).
  calc_format_examples_example_kind(t.format_examples_id) AS example_kind       -- 'counter' when IsCounter is true, else 'positive'. Convenience label.
FROM format_examples t;

-- ----------------------------------------------------------------------------
-- vw_enums: Top-level enum definitions (name-level). Versioned enums have multiple EnumVersions; literal enums have one. Sourced from definitions/registry.yaml + definitions/enums/.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW vw_enums WITH (security_invoker = ON) AS
SELECT
  t.enums_id,                                                                   -- Primary key (auto-synthesized: Enums had no field named 'Id' or ending in 'Id').
  t.name,                                                                       -- Enum identifier slug. Example: 'gw1.actor.class'. Acts as the primary key.
  t.owner,                                                                      -- Owner of this enum.
  t.enum_type,                                                                  -- Either 'versioned' (additive-only multi-version) or 'literal' (single immutable version).
  t.value_type,                                                                 -- JSON Schema datatype of the enum's symbols. If present, SHALL be 'integer' and version YAML files SHALL have type: integer. If null, the enum SHALL be treated as string-valued.
  t.description,                                                                -- Name-level description (registry-level).
  t.replaced_by,                                                                -- Advisory pointer to another Enum that supersedes this one. The original Enum remains valid and queryable — ReplacedBy is just a hint to consumers about a preferred successor. NOT a state change; published versions are immutable.
  t.raw_json,                                                                   -- Escape hatch: any unmodeled YAML keys (e.g., x-gridworks extended_description). JSON-encoded.
  calc_enums_is_versioned(t.enums_id) AS is_versioned,                          -- True when EnumType is 'versioned' (additive-only multi-version enum).
  calc_enums_is_literal(t.enums_id) AS is_literal,                              -- True when EnumType is 'literal' (single immutable version, frozen vocabulary).
  calc_enums_is_integer_valued(t.enums_id) AS is_integer_valued,                -- True when ValueType is 'integer' (otherwise the enum's symbols are strings).
  calc_enums_version_count(t.enums_id) AS version_count,                        -- Number of EnumVersions for this enum.
  calc_enums_draft_version_count(t.enums_id) AS draft_version_count,            -- Number of EnumVersions of this Word with Status='draft'.
  calc_enums_published_version_count(t.enums_id) AS published_version_count,    -- Number of published EnumVersions.
  calc_enums_has_drafts(t.enums_id) AS has_drafts,                              -- True iff this Word has at least one draft Definition.
  calc_enums_first_created(t.enums_id) AS first_created,                        -- When the first EnumVersion for this Word was created.
  calc_enums_last_modified(t.enums_id) AS last_modified                         -- Latest EnumVersions.Created among this Word's Definitions.
FROM enums t;

-- ----------------------------------------------------------------------------
-- vw_enum_versions: Specific versions of an enum. Each enum can have multiple versions (e.g. gw1.actor.class has versions 009, 010, 011).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW vw_enum_versions WITH (security_invoker = ON) AS
SELECT
  t.enum_versions_id,                                                           -- Primary key (auto-synthesized: EnumVersions had no field named 'Id' or ending in 'Id').
  calc_enum_versions_name(t.enum_versions_id) AS name,                          -- Compound key: <enum-name>/<version>.
  t.enum,                                                                       -- Foreign key to the parent Enum.
  t.version,                                                                    -- Three-digit version string. Example: '007'.
  t.schema_url,                                                                 -- Schema URL from JSON-Schema $id.
  t.title,                                                                      -- Human-readable title.
  t.description,                                                                -- Version-specific description.
  t.default_symbol,                                                             -- The default symbol value for this version.
  t.status,                                                                     -- Lifecycle status. One of 'draft' (still being designed; mutable) or 'published' (promoted; immutable thereafter). Versions never leave 'published' — successors are introduced as new versions, optionally pointed at via the parent Word's ReplacedBy.
  t.created,                                                                    -- Creation timestamp from registry.yaml.
  t.raw_json,                                                                   -- Escape hatch: any unmodeled YAML keys (e.g., type: integer for non-string enums, x-gridworks extended_description). JSON-encoded.
  calc_enum_versions_is_published(t.enum_versions_id) AS is_published,          -- True when Status is 'published'.
  calc_enum_versions_is_draft(t.enum_versions_id) AS is_draft,                  -- True when Status is 'draft'. Drives the Editor's 'Edit unlocked' affordance.
  calc_enum_versions_has_default_symbol(t.enum_versions_id) AS has_default_symbol,-- True when DefaultSymbol is set on this version.
  calc_enum_versions_value_count(t.enum_versions_id) AS value_count,            -- Number of EnumValues (symbols) declared in this version.
  calc_enum_versions_type_attribute_usage_count(t.enum_versions_id) AS type_attribute_usage_count,-- Number of TypeAttributes that point at this EnumVersion via EnumVersionRef.
  calc_enum_versions_type_helper_attribute_usage_count(t.enum_versions_id) AS type_helper_attribute_usage_count,-- Number of TypeHelperAttributes that point at this EnumVersion via EnumVersionRef.
  calc_enum_versions_outgoing_projection_count(t.enum_versions_id) AS outgoing_projection_count,-- Number of Projections starting from this version (i.e. where this is FromEnumVersion).
  calc_enum_versions_incoming_projection_count(t.enum_versions_id) AS incoming_projection_count,-- Number of Projections landing on this version (i.e. where this is ToEnumVersion).
  calc_enum_versions_outgoing_upgrade_count(t.enum_versions_id) AS outgoing_upgrade_count,-- Number of EnumUpgrades that bump from this version.
  calc_enum_versions_upgrade_template_out_count(t.enum_versions_id) AS upgrade_template_out_count,-- Number of upgrade Templates whose UpgradeFromEnumVersion is this EnumVersion.
  calc_enum_versions_has_upgrade_template(t.enum_versions_id) AS has_upgrade_template,-- True iff this EnumVersion has at least one outgoing upgrade template wired in.
  calc_enum_versions_incoming_upgrade_count(t.enum_versions_id) AS incoming_upgrade_count,-- Number of EnumUpgrades that bump to this version.
  calc_enum_versions_type_upgrade_op_usage_count(t.enum_versions_id) AS type_upgrade_op_usage_count,-- Number of TypeUpgradeOps referencing this version (via EnumVersionRef on EnumVersionBump / CoerceToEnum ops).
  calc_enum_versions_total_attribute_usage_count(t.enum_versions_id) AS total_attribute_usage_count,-- Total references across TypeAttributes + TypeHelperAttributes.
  calc_enum_versions_is_used_by_attributes(t.enum_versions_id) AS is_used_by_attributes,-- True when at least one attribute references this enum version.
  calc_enum_versions_has_incoming_projection(t.enum_versions_id) AS has_incoming_projection,-- True when at least one Projection lands on this version.
  calc_enum_versions_has_outgoing_projection(t.enum_versions_id) AS has_outgoing_projection,-- True when at least one Projection starts from this version.
  calc_enum_versions_has_incoming_upgrade(t.enum_versions_id) AS has_incoming_upgrade,-- True when at least one EnumUpgrade bumps to this version (this version was reached from a predecessor).
  calc_enum_versions_has_outgoing_upgrade(t.enum_versions_id) AS has_outgoing_upgrade,-- True when at least one EnumUpgrade bumps from this version (this version has a successor).
  calc_enum_versions_is_root(t.enum_versions_id) AS is_root,                    -- True when this version has no incoming upgrade — it was created fresh, not bumped from a predecessor.
  calc_enum_versions_is_leaf(t.enum_versions_id) AS is_leaf,                    -- True when this version has no outgoing upgrade — it has no successor and is a tip of the version chain.
  calc_enum_versions_owner_name(t.enum_versions_id) AS owner_name,              -- Owner of this EnumVersion's Word, passed through from Enums.Owner.
  calc_enum_versions_word_description(t.enum_versions_id) AS word_description,  -- Description of the parent Enum.
  t.last_modified,                                                              -- Most recent edit to this EnumVersion or its child EnumValues.
  t.promoted_at,                                                                -- When Status flipped from draft to active.
  calc_enum_versions_is_promotable(t.enum_versions_id) AS is_promotable         -- True iff this draft EnumVersion can be promoted: it is a draft and has at least one symbol.
FROM enum_versions t;

